import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const TABS = ["Нүүр", "Сагс", "Профайл"];

function App() {
  const [tab, setTab] = useState("Нүүр");
  return (
    <View style={styles.container}>
      <Text nativeID="body" style={styles.body}>{tab}</Text>
      <View style={styles.tabbar}>
        {TABS.map((t, i) => (
          <Pressable key={t} nativeID={"tab" + i} testID="tab" style={styles.tab}>
            {/* энд бичнэ үү: onPress-оор tab солиж, идэвхтэйг тодотго */}
            <Text style={styles.tabText}>{t}</Text>
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  body: { flex: 1, textAlign: "center", textAlignVertical: "center", fontSize: 24, fontWeight: "bold" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  active: { backgroundColor: "#dbeafe" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const TABS = ["Нүүр", "Сагс", "Профайл"];

function App() {
  const [tab, setTab] = useState("Нүүр");
  return (
    <View style={styles.container}>
      <Text nativeID="body" style={styles.body}>{tab}</Text>
      <View style={styles.tabbar}>
        {TABS.map((t, i) => (
          <Pressable key={t} nativeID={"tab" + i} testID="tab" onPress={() => setTab(t)}
            style={[styles.tab, tab === t && styles.active]}>
            <Text style={styles.tabText}>{t}</Text>
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  body: { flex: 1, textAlign: "center", textAlignVertical: "center", fontSize: 24, fontWeight: "bold" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  active: { backgroundColor: "#dbeafe" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);
